cd "$(dirname "$0")"
mkdir -p site plain capped stalled held
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from surl' > plain/hello.txt
printf '%s\n' 'hello from surl' > capped/hello.txt
